const inputItem = $input.first();
const item = inputItem.json;

// SSH/Deploy-Fehler ueber den Error-Output erkennen (echter Node-Crash, fail-closed).
const executionError = inputItem.error || item.error;

// Build-Fehlschlag ueber das SSH-Node-Datenformat erkennen: Check_Build_Exit_Code
// leitet nicht-0-Exit-Codes ueber einen normalen IF-Zweig weiter (kein Node-Error!),
// das Item hat dann { code, stdout, stderr } statt QA_Gatekeeper's { output/text }.
const isBuildFailure = !executionError && typeof item.code === 'number';

let summary = '';
let formattedIssues = '';
let title = '';

if (executionError) {
  title = 'Deploy fehlgeschlagen (unerwarteter Fehler)';
  summary = (typeof executionError === 'string')
    ? executionError
    : (executionError.message || JSON.stringify(executionError));
} else if (isBuildFailure) {
  const stderrAll = (item.stderr || '').trim();
  const stdoutAll = (item.stdout || '').trim();
  // Health-Check nach dem Start (Punkt A, 23.09.): Build_Command_Builder schreibt bei Fehlschlag einen Marker + Log-Auszug.
  const hcIdx = stderrAll.indexOf('HEALTHCHECK_FAILED:');
  if (hcIdx !== -1) {
    title = 'Deploy fehlgeschlagen: App nicht funktionsfähig (Health-Check)';
    const hcLines = stderrAll.substring(hcIdx).split('\n');
    const hcHead = hcLines[0].replace('HEALTHCHECK_FAILED:', '').trim();
    const hcLog = hcLines.slice(1).join('\n').trim();
    summary = `${hcHead}\n\nDer Build war erfolgreich, aber die App startet nicht, stürzt ab oder antwortet auf / mit einem Fehlerstatus (4xx/5xx, z. B. 404 bei fehlender Startseite). Der Container bleibt zur Fehlersuche stehen, es wurde kein GitHub-Repo angelegt.${hcLog ? '\n\n**Log-Auszug:**\n```\n' + hcLog + '\n```' : ''}`;
  } else {
    title = `Deploy fehlgeschlagen (Build_And_Run, Exit Code ${item.code})`;
    // Seit dem '&&'-Fix enthält stderr bei Build-Fehlern das komplette Build-Log -> nur die letzten 40 Zeilen zeigen.
    const raw = stderrAll || stdoutAll;
    const lines = raw.split('\n');
    summary = raw
      ? (lines.length > 40 ? '(gekürzt, letzte 40 Zeilen)\n```\n' + lines.slice(-40).join('\n') + '\n```' : raw)
      : 'Kein stdout/stderr vom Build-Befehl erhalten.';
  }
} else {
  title = 'QA-Pruefung fehlgeschlagen (REJECTED)';
  let rawContent = item.output || item.text || item.response || item;

  if (typeof rawContent === 'string') {
    try {
      const cleaned = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();
      rawContent = JSON.parse(cleaned);
    } catch (e) {
      rawContent = { chat_summary: rawContent, issues: [] };
    }
  }

  summary = rawContent.chat_summary || 'Build durch QA-Gatekeeper abgelehnt.';

  if (Array.isArray(rawContent.issues)) {
    formattedIssues = rawContent.issues.map(iss => {
      if (typeof iss === 'string') return iss;
      return `${iss.file ? `[${iss.file}] ` : ''}${iss.issue || iss.message || JSON.stringify(iss)}`;
    }).join('\n- ');
  }
}

const message = `❌ **${title}**\n\n${summary}${formattedIssues ? '\n\n**Festgestellte Probleme:**\n- ' + formattedIssues : ''}`;

return [{
  json: {
    response: message,
    output: message
  }
}];

const items = $input.all();
const results = [];

function sanitizeCtrl(t){let r="";let inStr=false;let esc=false;for(let i=0;i<t.length;i++){const c=t[i];const cc=t.charCodeAt(i);if(inStr){if(esc){r+=c;esc=false;}else if(cc===92){r+=c;esc=true;}else if(cc===34){r+=c;inStr=false;}else if(cc===10){r+="\\n";}else if(cc===13){r+="\\r";}else if(cc===9){r+="\\t";}else{r+=c;}}else{if(cc===34){inStr=true;}r+=c;}}return r;}

const VALID_ESC = { '"': '"', '\\': '\\', '/': '/', b: '\b', f: '\f', n: '\n', r: '\r', t: '\t' };
// Toleranter JSON-String-Decoder: gültige Escapes wie JSON; ungültige Escape-Sequenzen (z. B. \d, \', \$) bleiben als Backslash+Zeichen erhalten.
function lenientUnescape(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c !== '\\') { out += c; continue; }
    const n = s[i + 1];
    if (n === undefined) { out += '\\'; break; }
    if (n === 'u' && /^[0-9a-fA-F]{4}$/.test(s.slice(i + 2, i + 6))) { out += String.fromCharCode(parseInt(s.slice(i + 2, i + 6), 16)); i += 5; continue; }
    if (Object.prototype.hasOwnProperty.call(VALID_ESC, n)) { out += VALID_ESC[n]; i += 1; continue; }
    out += '\\' + n; i += 1;
  }
  return out;
}

function isUnsafePath(p) {
  const norm = String(p).replace(/\\/g, '/').replace(/^\/+/, '');
  return norm === '' || norm.split('/').some(seg => seg === '..') || /^[A-Za-z]:/.test(norm) || norm.indexOf('\u0000') !== -1;
}

// opts.forceTolerant: nur für Tests (Stufe 2 auch bei gültigem JSON erzwingen)
function extractFiles(rawText, opts) {
  const o = opts || {};
  const res = { files: [], method: 'none', plausible: false, problems: [], warnings: [], truncated: false, truncatedPath: null, expected: 0 };
  const text = String(rawText === undefined || rawText === null ? '' : rawText);
  const first = text.indexOf('{');
  if (first === -1) { res.problems.push('kein JSON-Objekt im Text gefunden'); return res; }
  const last = text.lastIndexOf('}');
  const cand = last > first ? text.slice(first, last + 1) : text.slice(first);
  const tail = text.slice(first);
  const structural = (tail.match(/\{\s*"path"\s*:\s*"[^"]*"\s*,\s*"content"\s*:\s*"/g) || []).length;

  // Stufe 1: striktes JSON
  if (!o.forceTolerant) {
    try {
      const parsed = JSON.parse(sanitizeCtrl(cand));
      const arr = parsed && Array.isArray(parsed.files) ? parsed.files : null;
      if (arr) {
        res.files = arr.map(f => ({ path: String((f && (f.path || f.filename)) || ''), content: typeof (f && f.content) === 'string' ? f.content : '' }));
        res.method = 'json';
        res.expected = arr.length;
      } else { res.warnings.push('gültiges JSON, aber kein files-Array – wechsle zur toleranten Extraktion'); }
    } catch (e) { /* weiter mit Stufe 2 */ }
  }

  // Stufe 2: tolerante Einzeldatei-Extraktion
  if (res.method === 'none') {
    // Eintragsende = ein UNESCAPTES " (gerade Anzahl Backslashes davor), gefolgt von "}" und danach entweder ", {"path":" (nächster Eintrag) oder "]" (Array-Ende).
    // Rohe/falsch escapte " im Inhalt (z. B. `\""`, verbatim eingebettete Codeblöcke) und escaptes JSON im Inhalt (`\"}]`) beenden den Eintrag damit nicht.
    const startRe = /\{\s*"path"\s*:\s*"([^"]+)"\s*,\s*"content"\s*:\s*"/g;
    const endRe = /^\s*\}(?=\s*(?:,\s*\{\s*"path"\s*:|\]))/;
    const files = [];
    let sm, lastEnd = -1, incompletePath = null;
    while ((sm = startRe.exec(tail)) !== null) {
      const contentStart = startRe.lastIndex;
      let i = contentStart, endIdx = -1, contentEnd = -1;
      for (;;) {
        const q = tail.indexOf('"', i);
        if (q === -1) break;
        let bs = 0; for (let k = q - 1; k >= 0 && tail[k] === '\\'; k--) bs++;
        if (bs % 2 === 0) {
          const em = endRe.exec(tail.slice(q + 1, q + 1 + 400));
          if (em) { endIdx = q + 1 + em[0].length; contentEnd = q; break; }
        }
        i = q + 1;
      }
      if (endIdx === -1) { incompletePath = sm[1]; break; }
      files.push({ path: lenientUnescape(sm[1]), content: lenientUnescape(tail.slice(contentStart, contentEnd)) });
      lastEnd = endIdx; startRe.lastIndex = endIdx;
    }
    res.files = files; res.method = files.length ? 'tolerant' : 'none'; res.expected = structural;
    const remainder = lastEnd === -1 ? tail : tail.slice(lastEnd);
    if (incompletePath === null && lastEnd !== -1 && /^\s*\]/.test(remainder)) {
      // Array ordnungsgemäß geschlossen -> Struktur vollständig
    } else if (structural > 0) {
      res.truncated = true; res.truncatedPath = incompletePath;
    }
  }

  // Stufe 3: Plausibilität (problems = hart -> Retry/fail-closed; warnings = nur Hinweis)
  if (res.files.length === 0) res.problems.push('keine Dateien extrahierbar');
  if (res.method === 'tolerant' && res.expected !== res.files.length) res.problems.push('Anzahl: ' + res.files.length + ' extrahiert, ' + res.expected + ' erwartet');
  if (res.truncated) res.problems.push('Ausgabe unvollständig/abgeschnitten' + (res.truncatedPath ? ' (Datei ' + res.truncatedPath + ' nicht abgeschlossen)' : ''));
  for (const f of res.files) {
    if (isUnsafePath(f.path)) res.problems.push('unsicherer oder leerer Pfad: ' + JSON.stringify(f.path));
    if (!f.content || !f.content.trim()) res.problems.push('leerer Inhalt: ' + f.path);
    if (/\.html?$/i.test(f.path) && !/<\/html>/i.test(f.content)) res.warnings.push('HTML ohne </html>: ' + f.path);
  }
  res.plausible = res.problems.length === 0;
  return res;
}

// Punkt H, Variante B (24.09.): deployt wird die Dev-Fassung (letzter Aggregate_Files-Lauf), die die QA geprüft hat.
// Aus der QA-Ausgabe kommen nur README.md und .env.example; von der QA mitgelieferter Code wird ignoriert (und vermerkt).
const RELEASE_FILES = ["README.md", ".env.example"];
const REQUIRED_DEV_FILES = ["index.html", "main.py", "requirements.txt"];
const normPath = (p) => String(p || "").replace(/\\/g, "/").replace(/^\/+/g, "");

let devFiles = null;
try { devFiles = $("Aggregate_Files").first().json.files; } catch (e) { devFiles = null; }
if (!Array.isArray(devFiles)) {
  throw new Error("Dev-Fassung (Aggregate_Files) nicht lesbar – Abbruch (fail-closed).");
}
const devByPath = new Map(devFiles.map(f => [normPath(f.path), f.content]));
const missingDev = REQUIRED_DEV_FILES.filter(p => !devByPath.has(p) || !String(devByPath.get(p) || "").trim());
if (missingDev.length) {
  throw new Error(`Dev-Fassung unvollständig (fehlt/leer: ${missingDev.join(", ")}) – Abbruch (fail-closed).`);
}
for (const p of devByPath.keys()) {
  if (isUnsafePath(p)) throw new Error(`Dev-Fassung mit unsicherem Pfad ${JSON.stringify(p)} – Abbruch (fail-closed).`);
}

const item = items[0];
const rawText = (item && (item.json.output || item.json.text)) || "";
const ex = extractFiles(rawText);
if (!ex.plausible) {
  throw new Error(`QA-Output nicht zuverlässig lesbar (${ex.problems.join("; ")}) – Abbruch (fail-closed) statt stillschweigend unvollständigem Deploy.`);
}
const qaRelease = new Map();
const qaIgnored = [];
for (const f of ex.files) {
  const p = normPath(f.path);
  if (RELEASE_FILES.includes(p)) qaRelease.set(p, f.content || "");
  else qaIgnored.push(p);
}

const finalFiles = [];
for (const [p, content] of devByPath) {
  if (RELEASE_FILES.includes(p) && qaRelease.has(p)) continue; // Release-Artefakte der QA haben Vorrang
  finalFiles.push({ path: p, content: content || "", source: "dev" });
}
for (const [p, content] of qaRelease) finalFiles.push({ path: p, content, source: "qa" });

for (const f of finalFiles) {
  results.push({
    json: { file_name: f.path, parse_method: ex.method, source: f.source, qa_code_files_ignored: qaIgnored },
    binary: {
      data: await this.helpers.prepareBinaryData(
        Buffer.from(f.content, "utf-8"),
        f.path
      )
    }
  });
}

if (results.length === 0) {
  throw new Error("Keine Dateien im files-Array des QA-Gatekeepers gefunden. Überprüfe das Raw-Format.");
}

return results;

const firstItem = $input.first().json;
const summary = firstItem.chat_summary || 'Alle Dateien wurden im Staging-Ordner gespeichert und der Dienst neu gestartet.';

const buildInfo = $('Build_Command_Builder').first().json;
const dockerSrvIp = $('Config').first().json.docker_srv_ip;
const appUrl = `http://${dockerSrvIp}:${buildInfo.port}/`;

const message = `✅ **Build & QA erfolgreich abgeschlossen!**\n\n${summary}\n\n🔗 **Live auf Staging:** [${appUrl}](${appUrl})`;

return [{
  json: {
    response: message,
    output: message
  }
}];

// 1. Text aus dem Product Owner Node extrahieren
const rawOutput = $json.output || $json.text || "";

// 2. Markdown-Fences entfernen & JSON-Block isolieren
let cleaned = rawOutput.replace(/```json/gi, "").replace(/```/gi, "").trim();

const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');

let spec = {};
if (firstBrace !== -1 && lastBrace !== -1) {
  try {
    spec = JSON.parse(cleaned.substring(firstBrace, lastBrace + 1));
  } catch (e) {
    spec = {};
  }
}

// 3. Dynamische Werte mit sauberen Fallbacks
const projectName = spec.project_name || "Dynamische Applikation";
const archSpec = spec.architecture_spec || {};
const uiSpec = spec.ui_ux_spec || {};
const qaSpec = spec.qa_spec || {};
// Punkt C (24.09.): developer_spec + qa_spec gehen jetzt auch an die Dev-Agenten (vorher nur an die QA)
const devSpec = spec.developer_spec || {};
const endpoints = archSpec.api_routes || ["GET /api/data"];

// 3b. Projekt-Slug generieren (Baustein 1, Multi-Projekt-Umbau)
// Slug = App-Name (kleingeschrieben, Sonderzeichen -> Bindestrich) + kurzer Zufalls-Hash,
// damit jedes Projekt spaeter einen eigenen Ordner/Container/Repo-Namen bekommt.
function slugify(text) {
  return text
    .toString()
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'projekt';
}
const shortHash = Math.random().toString(16).slice(2, 8);
const projectSlug = `${slugify(projectName)}-${shortHash}`;

