  const ex = extractFiles(rawText);
  allFiles.push(...ex.files.map(f => ({ path: f.path, content: f.content })));
  for (const p of ex.problems) parseErrors.push({ stage: "extract_" + ex.method, error: p, preview: rawText.substring(0, 200) });
}

// Revision-Loop: Zaehler + Merge mit vorherigem Dateistand (Punkt 5 Roadmap, Feedback-/Bugfix-Agent).
let revisionAttempt = 0;
try { revisionAttempt = $('Format_Correction_Payload').first().json.revision_attempt ?? 0; } catch (e) { revisionAttempt = 0; }

let finalFiles = allFiles;
if (revisionAttempt > 0) {
  let previousFiles = [];
  try { previousFiles = $('Aggregate_Files').first().json.files || []; } catch (e) { previousFiles = []; }
  const merged = [...previousFiles];
  for (const patched of allFiles) {
    const idx = merged.findIndex(f => f.path === patched.path);
    if (idx >= 0) merged[idx] = patched; else merged.push(patched);
  }
  finalFiles = merged;
}

// Holen der Specs aus dem Workflow-Kontext (vom Product Owner oder vorherigen Schritten)
let architecture_spec = {};
let qa_spec = {};
let developer_spec = {};
let platform_facts = [];
try {
  const poData = $('Format_Dev_Payload').first().json;
  architecture_spec = poData.architecture_spec || {};
  qa_spec = poData.qa_spec || {};
  // Punkt H (24.09.): QA prüft auch gegen developer_spec und die Plattform-Fakten
  developer_spec = (poData.raw_spec && poData.raw_spec.developer_spec) || {};
  platform_facts = poData.platform_facts || [];
  } catch (e) {
    parseErrors.push({ stage: "spec_lookup", error: e.message });
}

const payload = {
  files: finalFiles,
  architecture_spec: architecture_spec,
  qa_spec: qa_spec,
  developer_spec: developer_spec,
  platform_facts: platform_facts,
  parseErrors: parseErrors
};

return [{
  json: {
    files: finalFiles,
    revision_attempt: revisionAttempt,
    parseErrors: parseErrors,
    qa_input_payload: JSON.stringify(payload)
  }
}];

const slug = $('Format_Dev_Payload').first().json.project_slug;
const port = $('Port_Counter').first().json.stdout;

const dockerfileLines = [
  'FROM python:3.11-slim',
  'WORKDIR /app',
  'COPY requirements.txt .',
  'RUN pip install --no-cache-dir -r requirements.txt',
  'COPY . .',
  'EXPOSE 8000',
  'CMD ["uvicorn", "main:app", "--host", "0.0.0.0", "--port", "8000"]'
];
const printfArgs = dockerfileLines.map(l => `'${l}'`).join(' ');

// Health-Check nach dem Start (Punkt A, 23.09.): 2 s warten, dann bis zu 5 Versuche im Abstand von 1 s.
// Restart-Policy (24.09.): Container starten mit '--restart unless-stopped'; im Fehlerzweig wird sie vor exit 97 auf 'no' gesetzt.
// Gesund = Container läuft UND HTTP-Antwort auf / mit Status < 400 (Redirects zählen als gesund; 404 seit 24.09. krank).
// Sonst Exit 97 + Log-Auszug nach stderr -> Check_Build_Exit_Code (false) -> Format_Reject_Response (fail-closed).
// Toter Container bleibt für die Fehlersuche stehen. Bewusst ohne doppelte geschweifte Klammern (docker inspect -f),
// damit im SSH-Command-Feld nichts wie ein n8n-Ausdruck aussieht.
const healthCheck = [
  'sleep 2',
  'hc_ok=0',
  'hc_code=000',
  'hc_run=',
  'for i in 1 2 3 4 5; do ' +
    `hc_run=$(docker ps --filter status=running --filter name=${slug} | awk '{print $NF}' | grep -x -- '${slug}'); ` +
    // Restart-Policy (24.09.): ein zwischenzeitlich neu gestarteter Container gilt als krank (RestartCount muss 0 sein).
    `if ! docker inspect ${slug} | grep -q '"RestartCount": 0,'; then hc_run=; fi; ` +
    `hc_code=$(curl -s -o /dev/null -m 2 -w '%{http_code}' http://localhost:${port}/); ` +
    'if [ -n "$hc_run" ] && [ "$hc_code" -ge 100 ] && [ "$hc_code" -lt 400 ]; then hc_ok=1; break; fi; ' +
    'if [ $i -lt 5 ]; then sleep 1; fi; ' +
  'done',
  'if [ $hc_ok -ne 1 ]; then ' +
    `echo "HEALTHCHECK_FAILED: App ${slug} antwortet nach 5 Versuchen nicht gesund (letzter HTTP-Status: $hc_code, Container läuft: $([ -n "$hc_run" ] && echo ja || echo nein))" >&2; ` +
    `echo "--- docker logs --tail 30 ${slug} ---" >&2; ` +
    `docker logs --tail 30 ${slug} >&2 2>&1; ` +
    // Restart-Policy (24.09.): Container bleibt zur Fehlersuche stehen, darf aber nicht endlos neu starten.
    `docker update --restart no ${slug} >/dev/null 2>&1; ` +
    'exit 97; ' +
  'fi',
  'echo "HEALTHCHECK_OK: HTTP $hc_code nach Versuch $i"'
].join('; ');

// '&&' statt ';' vor docker run (Punkt A, 23.09.): ein fehlgeschlagener Build bricht jetzt ab, statt docker run
// ohne Image zu starten (-> irreführender Pull-Fehler). docker rm -f darf fehlschlagen (Container existiert noch nicht).
const buildCommand = `printf '%s\\n' ${printfArgs} > /opt/projects/${slug}/Dockerfile && cd /opt/projects/${slug} && docker build -t ${slug} . && { docker rm -f ${slug} >/dev/null 2>&1 || true; } && docker run -d --restart unless-stopped --name ${slug} -p ${port}:8000 ${slug} && { ${healthCheck}; }`;

return [{ json: { build_command: buildCommand, project_slug: slug, port: port } }];

const PLACEHOLDER_CREDENTIAL_WORDS = /^(user|username|admin|root|guest|test|pass|password|passwd|secret|changeme|changeit|xxx+|placeholder|example|dummy|replace[-_]?me|123456|admin123|postgres|mongo|mysql|redis)$/i;

const PATTERNS = [
  { name: 'aws_access_key_id', re: /AKIA[0-9A-Z]{16}/g },
  { name: 'github_pat', re: /gh[pousr]_[A-Za-z0-9]{36,}/g },
  { name: 'private_key_header', re: /-----BEGIN (RSA |EC |OPENSSH |DSA |PGP )?PRIVATE KEY-----/g },
  { name: 'slack_token', re: /xox[baprs]-[0-9A-Za-z-]{10,48}/g },
  { name: 'google_api_key', re: /AIza[0-9A-Za-z\-_]{35}/g },
  { name: 'generic_secret_assignment', re: /(api[_-]?key|secret|token|passwd|password)\s*[:=]\s*['"]([A-Za-z0-9_\-\.\/+]{16,})['"]/gi },
  {
    name: 'db_connection_string_with_credentials',
    re: /(?:postgres(?:ql)?|mongodb(?:\+srv)?|mysql|redis):\/\/(?<user>[A-Za-z0-9_.%+-]+):(?<pass>[^\s@\/]+)@(?<host>[^\s\/'"]+)/gi,
    validate: (m) => !PLACEHOLDER_CREDENTIAL_WORDS.test(m.groups.pass),
  },
  { name: 'stripe_key', re: /sk_(?:live|test)_[A-Za-z0-9]{10,}/g },
  { name: 'openai_key', re: /sk-proj-[A-Za-z0-9_-]{20,}/g },
  { name: 'openai_key', re: /sk-(?!ant-|proj-)[A-Za-z0-9]{20,}/g },
  { name: 'anthropic_key', re: /sk-ant-[A-Za-z0-9_-]{10,}/g },
  { name: 'jwt', re: /eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g },
];

const PLACEHOLDER_HINTS = /your[-_]?(token|key|secret|password)|<[^>]+>|xxx+|changeme|placeholder|example|dummy|replace[-_]?me/i;
const PLACEHOLDER_FILES = /\.env\.example$|^readme\.md$/i;

function scanFile(fileName, text) {
  const isPlaceholderFile = PLACEHOLDER_FILES.test(fileName);
  const matches = [];
  for (const pattern of PATTERNS) {
    if (isPlaceholderFile && pattern.name === 'generic_secret_assignment') continue;
    for (const m of text.matchAll(pattern.re)) {
      const raw = m[0];
      if (PLACEHOLDER_HINTS.test(raw)) continue;
      if (pattern.validate && !pattern.validate(m)) continue;
      matches.push(pattern.name);
    }
  }
  return [...new Set(matches)];
}

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const fileName = item.json.file_name || '';
  let content = '';
  let readFailed = false;
  if (item.binary && item.binary.data) {
    // Live liegen Binaries im Dateisystem-Modus (.data = Marker) -> offizieller Helper statt Base64-Dekodierung
    try { content = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf-8'); } catch (e) { readFailed = true; }
  }
  // fail-closed: eine nicht lesbare Datei kann nicht als sauber gelten
  const matches = readFailed ? ['scan_read_error'] : scanFile(fileName, content);
  results.push({
    json: { ...item.json, secret_scan: { clean: matches.length === 0, matches } },
    binary: item.binary,
  });
}

const pipelineClean = results.every(r => r.json.secret_scan.clean);
for (const r of results) {
  r.json.secret_scan_pipeline_clean = pipelineClean;
}

return results;

