const rawOutput = $json.output || $json.text || "";
let cleaned = rawOutput.replace(/```json/gi, "").replace(/```/gi, "").trim();
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
let patch = {};
if (firstBrace !== -1 && lastBrace !== -1) {
  try { patch = JSON.parse(cleaned.substring(firstBrace, lastBrace + 1)); } catch (e) { patch = {}; }
}

let prevAttempt = 0;
try { prevAttempt = $('Aggregate_Files').first().json.revision_attempt ?? 0; } catch (e) { prevAttempt = 0; }
const revisionAttempt = prevAttempt + 1;

const backendFiles = patch.files_to_patch_backend || [];
const frontendFiles = patch.files_to_patch_frontend || [];

const result = { json: { revision_attempt: revisionAttempt, issues_addressed: patch.issues_addressed || '' } };

// Punkt C (24.09.): developer_spec + qa_spec auch im Korrekturmodus an die Dev-Agenten (Kontext, keine neuen Aufgaben)
let specContext = {};
try { const fdp = $('Format_Dev_Payload').first().json; const s = fdp.raw_spec || {}; specContext = { developer_spec: s.developer_spec || {}, qa_spec: s.qa_spec || {}, platform_facts: fdp.platform_facts || [] }; } catch (e) { specContext = {}; }

if (backendFiles.length > 0) {
  result.json.backend_payload = JSON.stringify({
    mode: "correction",
    task: "Apply a targeted fix to existing backend file(s). Do NOT rewrite unrelated files or add new features.",
    files_to_patch: backendFiles,
    ...specContext,
  });
}
if (frontendFiles.length > 0) {
  result.json.frontend_payload = JSON.stringify({
    mode: "correction",
    task: "Apply a targeted fix to existing frontend file(s). Do NOT rewrite unrelated files or add new features.",
    files_to_patch: frontendFiles,
    ...specContext,
  });
}

return [result];

const items = $input.all();
const blockedItems = items.filter(i => i.json.secret_scan !== undefined);
if (blockedItems.length > 0) {
  const affectedFiles = blockedItems.filter(i => !i.json.secret_scan.clean).map(i => i.json.file_name);
  const categories = [...new Set(blockedItems.flatMap(i => i.json.secret_scan.matches || []))];
  return [{ json: { github_status: 'blocked_secret',
    github_message: `⚠️ **GitHub-Push blockiert:** Möglicher Secret-Fund in ${affectedFiles.join(', ')} (Muster: ${categories.join(', ')}). Der Code wurde NICHT zu GitHub gepusht. Das Staging-Deployment lief unabhängig davon bereits erfolgreich.` } }];
}
return [{ json: { github_status: 'pushed', github_message: '' } }];

const baseMessage = $json.response || $json.output;
const githubOutcome = $('Format_GitHub_Outcome').first().json;
const complianceOutcome = $('Format_Compliance_Outcome').first().json;
const legalOutcome = $('Legal_Scan').first().json;
// Punkt G (26.09.): Mock-Scan-Hinweis, abgesichert – fehlt Node/Item/Feld, gibt es keinen Hinweis und keinen Fehler
let mockScan = null;
try { const m = $('Mock_Scan').first(); mockScan = (m && m.json && m.json.mock_scan) || null; } catch (e) { mockScan = null; }

let finalMessage = baseMessage;
if (githubOutcome.github_status === 'blocked_secret') {
  finalMessage = `${finalMessage}\n\n${githubOutcome.github_message}`;
}
if (complianceOutcome.compliance_status === 'flagged') {
  finalMessage = `${finalMessage}\n\n${complianceOutcome.compliance_message}`;
}
if (legalOutcome.legal_message) {
  finalMessage = `${finalMessage}\n\n${legalOutcome.legal_message}`;
}
if (mockScan && typeof mockScan.message === 'string' && mockScan.message) {
  finalMessage = `${finalMessage}\n\n${mockScan.message}`;
}
return [{ json: { response: finalMessage, output: finalMessage } }];

