function scanFile(text) {
  return PII_INDICATOR_PATTERNS.filter(p => p.re.test(text)).map(p => ({ name: p.name, tier: p.tier }));
}

const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  let indicators = [];
  if (item.binary && item.binary.data) {
    try {
      const content = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf-8');
      indicators = scanFile(content);
    } catch (e) {
      // fail-loud (informativer Agent, blockiert nie): Lesefehler wird als Indikator sichtbar gemacht
      indicators = [{ name: 'scan_read_error', tier: 'quasi' }];
    }
  }
  results.push({ json: { ...item.json, pii_indicators: indicators }, binary: item.binary });
}
const anyIndicator = results.some(r => r.json.pii_indicators.length > 0);
for (const r of results) r.json.pii_scan_triggered = anyIndicator;
return results;

const items = $input.all();
const flagged = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (item.json.pii_indicators.length === 0) continue;
  let content = '';
  if (item.binary && item.binary.data) {
    try { content = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf-8'); } catch (e) { content = '[Dateiinhalt nicht lesbar]'; }
  }
  flagged.push({ file_name: item.json.file_name, indicators: item.json.pii_indicators, content });
